-- Nov 28, 2021, 9:38:35 PM CET
INSERT INTO AD_ViewComponent (AD_Client_ID,AD_Org_ID,AD_ViewComponent_ID,AD_ViewComponent_UU,Created,CreatedBy,EntityType,IsActive,Name,Updated,UpdatedBy,AD_Table_ID,OtherClause,SeqNo,WhereClause,FromClause,IsUnionAll) VALUES (0,0,200019,'b337f467-e32e-4916-b309-f149b6f06365',TO_TIMESTAMP('2021-11-28 21:38:35','YYYY-MM-DD HH24:MI:SS'),100,'D','Y','c_invoice_candidate_v-010',TO_TIMESTAMP('2021-11-28 21:38:35','YYYY-MM-DD HH24:MI:SS'),100,200292,'GROUP BY o.ad_client_id, o.ad_org_id, o.c_bpartner_id, o.c_order_id, o.documentno, o.dateordered, o.c_doctype_id',10,'WHERE (o.docstatus IN (''CO'', ''CL'', ''IP'')) AND (o.c_doctype_id IN ( SELECT c_doctype.c_doctype_id
           FROM c_doctype
          WHERE c_doctype.docbasetype = ''SOO'' AND (c_doctype.docsubtypeso NOT IN (''ON'', ''OB'', ''WR'')))) AND l.qtyordered <> l.qtyinvoiced AND (o.invoicerule = ''I'' OR o.invoicerule = ''O'' AND NOT (EXISTS ( SELECT 1
           FROM c_orderline zz1
          WHERE zz1.c_order_id = o.c_order_id AND zz1.qtyordered <> zz1.qtydelivered)) OR o.invoicerule = ''D'' AND l.qtyinvoiced <> l.qtydelivered OR o.invoicerule = ''S'' AND bp.c_invoiceschedule_id IS NULL OR o.invoicerule = ''S'' AND bp.c_invoiceschedule_id IS NOT NULL AND (si.invoicefrequency IS NULL OR si.invoicefrequency = ''D'' OR si.invoicefrequency = ''W'' OR si.invoicefrequency = ''T'' AND (trunc(o.dateordered) <= (firstof(getdate(), ''MM'') + si.invoicedaycutoff - 1) AND trunc(getdate()) >= (firstof(o.dateordered, ''MM'') + si.invoiceday - 1) OR trunc(o.dateordered) <= (firstof(getdate(), ''MM'') + si.invoicedaycutoff + 14) AND trunc(getdate()) >= (firstof(o.dateordered, ''MM'') + si.invoiceday + 14)) OR si.invoicefrequency = ''M'' AND trunc(o.dateordered) <= (firstof(getdate(), ''MM'') + si.invoicedaycutoff - 1) AND trunc(getdate()) >= (firstof(o.dateordered, ''MM'') + si.invoiceday - 1)))','FROM c_order o
JOIN c_orderline l ON o.c_order_id = l.c_order_id
JOIN c_bpartner bp ON o.c_bpartner_id = bp.c_bpartner_id
LEFT JOIN c_invoiceschedule si ON bp.c_invoiceschedule_id = si.c_invoiceschedule_id','N')
;

