INSERT INTO AD_ViewComponent (AD_Client_ID,AD_Org_ID,AD_ViewComponent_ID,AD_ViewComponent_UU,Created,CreatedBy,EntityType,IsActive,Name,Updated,UpdatedBy,AD_Table_ID,SeqNo,FromClause,IsUnionAll) VALUES (0,0,200042,'9bc8d461-aa17-44ef-9de0-c011a6f87322',TO_TIMESTAMP('2021-11-28 21:38:42','YYYY-MM-DD HH24:MI:SS'),100,'D','Y','c_order_linetax_vt-010',TO_TIMESTAMP('2021-11-28 21:38:42','YYYY-MM-DD HH24:MI:SS'),100,200299,10,'FROM c_orderline ol
