INSERT INTO AD_ViewComponent (AD_Client_ID,AD_Org_ID,AD_ViewComponent_ID,AD_ViewComponent_UU,Created,CreatedBy,EntityType,IsActive,Name,Updated,UpdatedBy,AD_Table_ID,OtherClause,SeqNo,WhereClause,FromClause,IsUnionAll) VALUES (0,0,200065,'c4dacaaf-c5c8-4c98-8121-46c0500f2b1c',TO_TIMESTAMP('2021-11-28 21:38:49','YYYY-MM-DD HH24:MI:SS'),100,'D','Y','m_inout_candidate_v-010',TO_TIMESTAMP('2021-11-28 21:38:49','YYYY-MM-DD HH24:MI:SS'),100,200309,'GROUP BY o.ad_client_id, o.ad_org_id, o.c_bpartner_id, o.c_order_id, o.documentno, o.dateordered, o.c_doctype_id, o.poreference, o.description, o.salesrep_id, l.m_warehouse_id',10,'WHERE o.docstatus = ''CO'' AND o.isdelivered = ''N'' AND (o.c_doctype_id IN ( SELECT c_doctype.c_doctype_id
           FROM c_doctype
          WHERE c_doctype.docbasetype = ''SOO'' AND (c_doctype.docsubtypeso NOT IN (''ON'', ''OB'', ''WR'')))) AND o.deliveryrule <> ''M'' AND (l.m_product_id IS NULL OR (EXISTS ( SELECT 1
           FROM m_product p
          WHERE l.m_product_id = p.m_product_id AND p.isexcludeautodelivery = ''N''))) AND l.qtyordered <> l.qtydelivered AND (l.m_product_id IS NOT NULL OR l.c_charge_id IS NOT NULL) AND NOT (EXISTS ( SELECT 1
           FROM m_inoutline iol
             JOIN m_inout io ON iol.m_inout_id = io.m_inout_id
          WHERE iol.c_orderline_id = l.c_orderline_id AND (io.docstatus IN (''DR'', ''IN'', ''IP'', ''WC''))))','FROM c_order o
JOIN c_orderline l ON o.c_order_id = l.c_order_id','N')
;

