INSERT INTO AD_ViewComponent (AD_Client_ID,AD_Org_ID,AD_ViewComponent_ID,AD_ViewComponent_UU,Created,CreatedBy,EntityType,IsActive,Name,Updated,UpdatedBy,AD_Table_ID,SeqNo,WhereClause,FromClause,IsUnionAll) VALUES (0,0,200086,'adea973b-95a6-4786-b371-89597fd75c2d',TO_TIMESTAMP('2021-11-28 21:38:55','YYYY-MM-DD HH24:MI:SS'),100,'D','Y','m_packagelines_avail_v-010',TO_TIMESTAMP('2021-11-28 21:38:55','YYYY-MM-DD HH24:MI:SS'),100,200318,10,'WHERE p.ispicklistprintdetails = ''N'' AND iol.m_product_id <> COALESCE(ci.m_productfreight_id, 0) AND (iol.qtyentered - COALESCE(( SELECT sum(m_packageline.qty) AS sum
           FROM m_packageline
          WHERE m_packageline.m_inoutline_id = iol.m_inoutline_id), 0)) <> 0','FROM m_inoutline iol
LEFT JOIN m_packageline mpl ON iol.m_inoutline_id = mpl.m_inoutline_id
JOIN m_product p ON iol.m_product_id = p.m_product_id
