JOIN ad_clientinfo ci ON ci.ad_client_id = iol.ad_client_id','N')
;

-- Nov 28, 2021, 9:38:56 PM CET
INSERT INTO AD_ViewComponent (AD_Client_ID,AD_Org_ID,AD_ViewComponent_ID,AD_ViewComponent_UU,Created,CreatedBy,EntityType,IsActive,Name,Updated,UpdatedBy,AD_Table_ID,OtherClause,SeqNo,WhereClause,FromClause,IsUnionAll) VALUES (0,0,200087,'fe2d523b-758c-4582-ac5e-483d47137370',TO_TIMESTAMP('2021-11-28 21:38:56','YYYY-MM-DD HH24:MI:SS'),100,'D','Y','m_packagelines_avail_v-020',TO_TIMESTAMP('2021-11-28 21:38:56','YYYY-MM-DD HH24:MI:SS'),100,200318,'ORDER BY 1, 2, 3, 5',20,'WHERE p.isbom = ''Y'' AND p.isverified = ''Y'' AND p.ispicklistprintdetails = ''Y'' AND (iol.qtyentered * pbom.bomqty - COALESCE(( SELECT sum(m_packageline.qty) AS sum
           FROM m_packageline
          WHERE m_packageline.m_product_id = p2.m_product_id AND (m_packageline.m_package_id IN ( SELECT m_package.m_package_id
                   FROM m_package
                  WHERE m_package.m_inout_id = iol.m_inout_id))), 0)) <> 0','FROM m_inoutline iol
LEFT JOIN m_packageline mpl ON iol.m_inoutline_id = mpl.m_inoutline_id
JOIN m_product p ON iol.m_product_id = p.m_product_id
JOIN m_product_bom_old pbom ON p.m_product_id = pbom.m_product_id
JOIN m_product p2 ON pbom.m_productbom_id = p2.m_product_id
JOIN c_uom uom ON iol.c_uom_id = uom.c_uom_id','N')
;

